INSERT INTO painters (id, name, birth_year, death_year, bio_short) VALUES
  ('davinci', 'Leonardo da Vinci', 1452, 1519, '이탈리아 르네상스를 대표하는 화가이자 과학자'),
  ('michelangelo', 'Michelangelo', 1475, 1564, '시스티나 성당 천장화로 유명한 르네상스 거장'),
