  ('velazquez', 'Diego Velázquez', 1599, 1660, '스페인 궁정 화가, 바로크 회화의 정점'),
  ('goya', 'Francisco Goya', 1746, 1828, '스페인 궁정화가에서 전쟁의 참상을 그린 거장'),
  ('turner', 'J.M.W. Turner', 1775, 1851, '빛과 색의 실험으로 인상주의를 예고한 영국 화가'),
