  ('hokusai', 'Katsushika Hokusai', 1760, 1849, '일본 에도 시대의 목판화 거장'),
  ('hiroshige', 'Utagawa Hiroshige', 1797, 1858, '일본 명소 풍경 목판화의 대가'),
  ('vaneyck', 'Jan van Eyck', 1390, 1441, '세밀한 유화 기법을 완성한 초기 플랑드르 화가'),
