  ('durer', 'Albrecht Dürer', 1471, 1528, '북유럽 르네상스를 대표하는 화가이자 판화가'),
  ('bosch', 'Hieronymus Bosch', 1450, 1516, '기괴하고 환상적인 상상력의 플랑드르 화가'),
  ('elgreco', 'El Greco', 1541, 1614, '왜곡된 형태와 신비로운 색으로 그린 스페인 화가'),
  ('fragonard', 'Jean-Honoré Fragonard', 1732, 1806, '로코코 시대의 경쾌하고 관능적인 화가'),
  ('gainsborough', 'Thomas Gainsborough', 1727, 1788, '영국 초상화와 풍경화를 겸한 화가'),
  ('david', 'Jacques-Louis David', 1748, 1825, '프랑스 혁명기를 대표한 신고전주의 화가'),
  ('gericault', 'Théodore Géricault', 1791, 1824, '낭만주의 역사화의 선구자'),
  ('pissarro', 'Camille Pissarro', 1830, 1903, '도시 풍경을 인상주의로 담은 화가'),
  ('sargent', 'John Singer Sargent', 1856, 1925, '사교계 초상화로 명성을 얻은 미국 화가'),
  ('homer', 'Winslow Homer', 1836, 1910, '바다와 인간의 고투를 그린 미국 화가'),
  ('wood', 'Grant Wood', 1891, 1942, '미국 중서부 농촌을 그린 지방주의 화가'),
  ('millet', 'Jean-François Millet', 1814, 1875, '농민의 노동을 존엄하게 그린 프랑스 화가'),
  ('whistler', 'James Whistler', 1834, 1903, '색조의 조화를 음악처럼 탐구한 화가'),
  ('cassatt', 'Mary Cassatt', 1844, 1926, '모성과 일상을 그린 미국 출신 인상주의 화가'),
  ('corot', 'Camille Corot', 1796, 1875, '은빛 색조의 풍경화로 유명한 프랑스 화가'),
  ('blake', 'William Blake', 1757, 1827, '신비주의적 상상력의 영국 시인화가'),
  ('moreau', 'Gustave Moreau', 1826, 1898, '신화와 상징을 그린 프랑스 상징주의 화가'),
  ('redon', 'Odilon Redon', 1840, 1916, '꿈과 환상을 그린 프랑스 상징주의 화가'),
  ('morisot', 'Berthe Morisot', 1841, 1895, '인상주의 창립 멤버 중 한 명인 여성 화가'),
  ('bierstadt', 'Albert Bierstadt', 1830, 1902, '미국 서부의 장엄한 풍경을 그린 화가'),
  ('church', 'Frederic Edwin Church', 1826, 1900, '미국 허드슨 리버 화파의 풍경화가'),
  ('vigee-lebrun', 'Élisabeth Vigée Le Brun', 1755, 1842, '프랑스 왕비의 초상화가로 활동한 여성 화가'),
  ('canaletto', 'Canaletto', 1697, 1768, '베네치아 풍경을 정밀하게 그린 화가'),
  ('zurbaran', 'Francisco de Zurbarán', 1598, 1664, '정적이고 신비로운 정물화의 스페인 화가'),
  ('titian', 'Titian', 1488, 1576, '베네치아 화파를 대표하는 색채의 거장'),
  ('holbein', 'Hans Holbein the Younger', 1497, 1543, '정교한 세부 묘사의 북유럽 궁정 화가'),
  ('vanderweyden', 'Rogier van der Weyden', 1400, 1464, '감정 표현이 풍부한 초기 플랑드르 화가'),
  ('chardin', 'Jean-Siméon Chardin', 1699, 1779, '정물화의 품격을 높인 프랑스 화가'),
  ('ribera', 'Jusepe de Ribera', 1591, 1652, '빛과 그림자의 대비가 강렬한 스페인 바로크 화가'),
  ('hals', 'Frans Hals', 1582, 1666, '생기 있는 붓질의 네덜란드 초상화가')
INSERT INTO paintings (id, painter_id, title, image_url, thumbnail_url, style_tag, docent_story, is_featured) VALUES
  ('mona-lisa', 'davinci', '모나리자', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg', 'renaissance', '세상에서 가장 유명한 미소의 주인공, 신원조차 명확히 밝혀지지 않았다.', TRUE),
  ('last-supper', 'davinci', '최후의 만찬', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Leonardo_da_Vinci_%281452-1519%29_-_The_Last_Supper_%281495-1498%29.jpg/1280px-Leonardo_da_Vinci_%281452-1519%29_-_The_Last_Supper_%281495-1498%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Leonardo_da_Vinci_%281452-1519%29_-_The_Last_Supper_%281495-1498%29.jpg/1280px-Leonardo_da_Vinci_%281452-1519%29_-_The_Last_Supper_%281495-1498%29.jpg', 'renaissance', '벽화 기법이 아닌 실험적 유화 기법으로 그려져 완성 직후부터 훼손이 시작됐다.', TRUE),
  ('vitruvian-man', 'davinci', '비트루비우스적 인간', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Da_Vinci_Vitruve_Luc_Viatour.jpg/1280px-Da_Vinci_Vitruve_Luc_Viatour.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Da_Vinci_Vitruve_Luc_Viatour.jpg/1280px-Da_Vinci_Vitruve_Luc_Viatour.jpg', 'renaissance', '인체 비율과 기하학의 완벽한 조화를 탐구한 드로잉.', FALSE),
  ('creation-of-adam', 'michelangelo', '아담의 창조', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg/1280px-Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg/1280px-Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg', 'renaissance', '신과 아담의 손가락이 닿을 듯 말 듯한 간극이 가장 유명한 장면.', TRUE),
  ('last-judgment', 'michelangelo', '최후의 심판', 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Michelangelo%2C_Giudizio_Universale_02.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Michelangelo%2C_Giudizio_Universale_02.jpg', 'renaissance', '완성 당시 누드 표현으로 거센 논란을 일으켰다.', FALSE),
  ('school-of-athens', 'raphael', '아테네 학당', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg/1280px-%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg/1280px-%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg', 'renaissance', '플라톤과 아리스토텔레스를 비롯한 고대 철학자들이 한자리에 모였다.', TRUE),
  ('sistine-madonna', 'raphael', '시스티나 마돈나', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Raphael_-_The_Sistine_Madonna_-_Google_Art_Project.jpg/1280px-Raphael_-_The_Sistine_Madonna_-_Google_Art_Project.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Raphael_-_The_Sistine_Madonna_-_Google_Art_Project.jpg/1280px-Raphael_-_The_Sistine_Madonna_-_Google_Art_Project.jpg', 'renaissance', '그림 하단의 두 천사는 오늘날 가장 많이 복제되는 이미지 중 하나다.', FALSE),
  ('birth-of-venus', 'botticelli', '비너스의 탄생', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/1280px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/1280px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg', 'renaissance', '조개껍질을 타고 태어난 비너스, 서양 미술사의 상징적 장면.', TRUE),
  ('primavera', 'botticelli', '봄', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Sandro_Botticelli_-_La_Primavera_-_Google_Art_Project.jpg/1280px-Sandro_Botticelli_-_La_Primavera_-_Google_Art_Project.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Sandro_Botticelli_-_La_Primavera_-_Google_Art_Project.jpg/1280px-Sandro_Botticelli_-_La_Primavera_-_Google_Art_Project.jpg', 'renaissance', '여덟 명이 넘는 신화 속 인물이 등장하는 복잡한 우화화.', FALSE),
  ('calling-of-matthew', 'caravaggio', '성 마태오의 부름', 'https://upload.wikimedia.org/wikipedia/commons/1/14/Calling-of-st-matthew.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/14/Calling-of-st-matthew.jpg', 'baroque', '극적인 빛줄기가 마태오를 선택하는 순간을 비춘다.', FALSE),
  ('judith-holofernes', 'caravaggio', '홀로페르네스의 목을 베는 유디트', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Judith_Beheading_Holofernes_-_Caravaggio.jpg/1280px-Judith_Beheading_Holofernes_-_Caravaggio.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Judith_Beheading_Holofernes_-_Caravaggio.jpg/1280px-Judith_Beheading_Holofernes_-_Caravaggio.jpg', 'baroque', '바로크 특유의 생생하고 폭력적인 사실주의를 보여준다.', FALSE),
  ('night-watch', 'rembrandt', '야경', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/The_Nightwatch_by_Rembrandt_-_Rijksmuseum.jpg/1280px-The_Nightwatch_by_Rembrandt_-_Rijksmuseum.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/The_Nightwatch_by_Rembrandt_-_Rijksmuseum.jpg/1280px-The_Nightwatch_by_Rembrandt_-_Rijksmuseum.jpg', 'baroque', '원래 제목은 야경이 아니었고, 그림이 어두워지며 붙은 이름이다.', TRUE),
  ('self-portrait-rembrandt', 'rembrandt', '자화상', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg/1280px-Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg/1280px-Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg', 'baroque', '평생 90여 점의 자화상을 남겨 스스로를 가장 많이 그린 화가로 꼽힌다.', FALSE),
  ('anatomy-lesson', 'rembrandt', '니콜라스 튈프 박사의 해부학 강의', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Rembrandt_-_The_Anatomy_Lesson_of_Dr_Nicolaes_Tulp.jpg/1280px-Rembrandt_-_The_Anatomy_Lesson_of_Dr_Nicolaes_Tulp.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Rembrandt_-_The_Anatomy_Lesson_of_Dr_Nicolaes_Tulp.jpg/1280px-Rembrandt_-_The_Anatomy_Lesson_of_Dr_Nicolaes_Tulp.jpg', 'baroque', '집단 초상화에 극적인 서사를 더한 혁신적 구성.', FALSE),
  ('milkmaid', 'vermeer', '우유 따르는 여인', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg/1280px-Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg/1280px-Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg', 'baroque', '일상의 한 순간을 성스러울 만큼 차분한 빛으로 담아냈다.', FALSE),
  ('view-of-delft', 'vermeer', '델프트 풍경', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Vermeer-view-of-delft.jpg/1280px-Vermeer-view-of-delft.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Vermeer-view-of-delft.jpg/1280px-Vermeer-view-of-delft.jpg', 'baroque', '현존하는 베르메르의 풍경화 두 점 중 하나.', FALSE),
  ('las-meninas', 'velazquez', '시녀들', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg/1280px-Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg/1280px-Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg', 'baroque', '거울 속 왕과 왕비, 캔버스 밖 화가까지 그림 속 시선이 교차한다.', TRUE),
